@GameTestHolder("kingdom_smp_archive_tests") @PrefixGameTestTemplate(false)
public final class EconomyArchiveRuntimeTests {
    private static long requests;
    @GameTest(template="empty",timeoutTicks=14000)
    public static void archiveRealEarnedProfessionAndFundedEscrowAcrossProcesses(GameTestHelper h)throws Exception{
        var path=proofPath(h);if(Files.exists(path)){var proof=AtomicNbt.read(path);restore(h,proof);return;}
        FarmerFullLoopRuntimeTests.fullLoop(h,()->guard(h,()->prepare(h)));
    }
    private static Path proofPath(GameTestHelper h){return h.getLevel().getServer().getWorldPath(LevelResource.ROOT).resolve("archive-runtime-proof.nbt");}
    private static void prepare(GameTestHelper h)throws Exception{
        var level=h.getLevel();var server=level.getServer();var hall=ConstructionService.lodge(server);var p=(ClaimRuntimeTests.ClaimPlayer)server.getPlayerList().getPlayer(hall.owner());var reviewer=(ClaimRuntimeTests.ClaimPlayer)server.getPlayerList().getPlayers().stream().filter(v->v!=p).findFirst().orElseThrow();var s=CommerceService.store(server);var bank=bank(h);near(p,level.getEntity(bank.npc()));near(reviewer,level.getEntity(bank.npc()));CommerceService.openResident(p,(ReeveEntity)level.getEntity(bank.npc()));CommerceService.openResident(reviewer,(ReeveEntity)level.getEntity(bank.npc()));
        // Claim only the actual earned Farmer/contract rewards, through the normal counter interface.
        for(var mail:new ArrayList<>(s.mailbox(p.getUUID())))if(mail.kind()==EconomyStore.MailKind.COINS&&!mail.claimed())claimCoins(p,mail.id());
        int empty=empty(p);p.getInventory().setItem(empty,new ItemStack(Items.COBBLESTONE));p.getInventory().selected=empty;var listing=AuctionService.review(p,5,"sell_timed",1,100);AuctionService.confirm(p,listing.nonce());var bid=AuctionService.review(reviewer,5,"bid:"+listing.nonce(),1,100);AuctionService.confirm(reviewer,bid.nonce());
        p.getInventory().setItem(empty,new ItemStack(Items.OAK_LOG));var order=BuyOrderService.review(p,"create",2,10);BuyOrderService.confirm(p,order.nonce());h.assertTrue(s.listing(listing.nonce()).orElseThrow().active()&&s.order(order.nonce()).orElseThrow().active(),"Real funded timed bid and buy order are open before archive");
        boolean denied=false;try{command(p,"kingdom admin economy archive inspect");}catch(com.mojang.brigadier.exceptions.CommandSyntaxException expected){denied=true;}h.assertTrue(denied,"Ordinary Master profession rank grants no administrator archive access");h.assertTrue(reviewer.hasPermissions(4),"The actual site-inspection administrator reviews maintenance");
        h.assertTrue(command(reviewer,"kingdom admin economy archive review Exact native escrow maintenance fixture")==1,"Administrator receives actual clickable review");String stale=confirmation(reviewer);s.queueCoins(UUID.randomUUID(),p.getUUID(),1,"Explicit stale-review fixture coin");h.assertTrue(command(reviewer,stale)==0&&s.archiveStatus().closedSegments()==0,"A changed journal invalidates maintenance review");
        var pending=s.prepareSale(UUID.randomUUID(),p.getUUID(),"minecraft:wheat",1,1,MarketService.day(),20000,10000,2000);h.assertTrue(command(reviewer,"kingdom admin economy archive review Must refuse pending inventory")==0,"Archive review refuses an unresolved native receipt");h.assertTrue(!s.recoverSale(CommerceService.loadedReceipt(p)),"Proven pre-removal native sale cancels before archive");h.assertTrue(s.pendingSale().isEmpty(),"Pending sale is reconciled without consuming fixture inventory");
        CommerceService.checkpoint(p);CommerceService.checkpoint(reviewer);long ownerReceipt=s.expectedReceipt(p.getUUID()),otherReceipt=s.expectedReceipt(reviewer.getUUID()),revision=s.revision();long balance=s.balance(p.getUUID()),otherBalance=s.balance(reviewer.getUUID());var nativeInventory=p.getInventory().save(new ListTag());
        command(reviewer,"kingdom admin economy archive review Preserve earned Farmer records and funded escrow");String confirmed=confirmation(reviewer);h.assertTrue(command(reviewer,confirmed)==1,"Exact reviewed archive command actually publishes immutable prefix");h.assertTrue(command(reviewer,confirmed)==0,"Replayed archive confirmation cannot run twice");h.assertTrue(s.revision()==revision&&s.balance(p.getUUID())==balance&&s.balance(reviewer.getUUID())==otherBalance&&s.expectedReceipt(p.getUUID())==ownerReceipt&&s.expectedReceipt(reviewer.getUUID())==otherReceipt&&nativeInventory.equals(p.getInventory().save(new ListTag())),"Archival preserves all financial values, global receipt sequences and physical inventory");
        h.assertTrue(s.archiveStatus().closedSegments()>0&&s.archiveStatus().activeOperations()==0,"Actual world uses closed schema-two journal");var proof=new CompoundTag();proof.putUUID("owner",p.getUUID());proof.putUUID("reviewer",reviewer.getUUID());proof.putUUID("listing",listing.nonce());proof.putUUID("order",order.nonce());proof.putUUID("builder",BuilderHutSavedData.get(server).hut().orElseThrow().npcId());proof.putUUID("bank",bank.npc());proof.put("construction",AtomicNbt.read(server.getWorldPath(LevelResource.ROOT).resolve("data/kingdomsmp_construction.dat")));proof.putInt("phase",1);capture(s,p,reviewer,proof);AtomicNbt.write(proofPath(h),proof);CommerceService.verifyReceipt(p);CommerceService.verifyReceipt(reviewer);
        com.mojang.logging.LogUtils.getLogger().info("ARCHIVE_PREPARED: actual earned24Farmer and both physical tools, real funded bid/order, administrator clickable/stale/pending/replay checks, canonical immutable prefix, unchanged purses/global receipts/native inventory. Existing Farmer quantity/growth/AI and supplied-material fixtures remain explicit.");h.succeed();
    }
    private static void restore(GameTestHelper h,CompoundTag proof)throws Exception{
        var level=h.getLevel();var p=ClaimRuntimeTests.player(level,proof.getUUID("owner"),"HallWinner");var other=ClaimRuntimeTests.player(level,proof.getUUID("reviewer"),"HallOwner");level.getServer().getPlayerList().deop(other.getGameProfile());h.assertTrue(!p.hasPermissions(2)&&!other.hasPermissions(2),"Restarted customers use public NPC access without operator privileges");var bank=bank(h);for(int x=-1;x<=6;x++)for(int z=0;z<=4;z++)level.getChunk(x,z);h.runAfterDelay(100,()->guard(h,()->{
            var s=CommerceService.store(level.getServer());h.assertTrue(s.revision()==proof.getLong("revision")&&s.balance(p.getUUID())==proof.getLong("ownerBalance")&&s.balance(other.getUUID())==proof.getLong("otherBalance"),"Actual JVM restart preserves both purses and global journal revision");h.assertTrue(s.expectedReceipt(p.getUUID())==proof.getLong("ownerReceipt")&&s.expectedReceipt(other.getUUID())==proof.getLong("otherReceipt"),"Archived native receipt sequence remains unchanged");CommerceService.verifyReceipt(p);CommerceService.verifyReceipt(other);verifyEarned(h,s,p);
            h.assertTrue(proof.getCompound("construction").equals(AtomicNbt.read(level.getServer().getWorldPath(LevelResource.ROOT).resolve("data/kingdomsmp_construction.dat"))),"Economy migration never rewrites kingdom construction/entitlement/NPC history");h.assertTrue(BuilderHutSavedData.get(level.getServer()).hut().orElseThrow().npcId().equals(proof.getUUID("builder"))&&bank.npc().equals(proof.getUUID("bank")),"Original Aldric and Banker records survive real restart");near(p,level.getEntity(bank.npc()));near(other,level.getEntity(bank.npc()));CommerceService.openResident(p,(ReeveEntity)level.getEntity(bank.npc()));CommerceService.openResident(other,(ReeveEntity)level.getEntity(bank.npc()));
            if(proof.getInt("phase")==1){
                var order=s.order(proof.getUUID("order")).orElseThrow();var listing=s.listing(proof.getUUID("listing")).orElseThrow();h.assertTrue(order.active()&&order.remaining()==2&&listing.active()&&listing.bidder().equals(other.getUUID())&&listing.bid()==100,"Actual restored escrow remains funded and redeemable");int slot=empty(other);other.getInventory().setItem(slot,new ItemStack(Items.OAK_LOG));other.getInventory().selected=slot;h.assertTrue(com.mohymods.kingdomsmp.placement.PlacementProtection.check(level,other,bank.origin(),bank.origin())!=null&&com.mohymods.kingdomsmp.placement.PlacementProtection.entityInteraction(other,level.getEntity(bank.npc()))==null,"Public NPC use with a held sample does not grant protected terrain editing");var fill=BuyOrderService.review(other,"fill:"+order.id(),1,0);BuyOrderService.confirm(other,fill.nonce());var cancel=BuyOrderService.review(p,"cancel:"+order.id(),1,0);BuyOrderService.confirm(p,cancel.nonce());
                s.settleTimed(UUID.randomUUID(),other.getUUID(),listing.id(),listing.expires(),"Explicit isolated archived-escrow deadline acceleration");for(var mail:new ArrayList<>(s.mailbox(p.getUUID())))if(mail.kind()==EconomyStore.MailKind.COINS&&!mail.claimed())claimCoins(p,mail.id());for(var mail:new ArrayList<>(s.mailbox(other.getUUID())))if(mail.kind()==EconomyStore.MailKind.COINS&&!mail.claimed())claimCoins(other,mail.id());for(var mail:new ArrayList<>(s.itemMailbox(p.getUUID())))if(!mail.claimed()){var q=AuctionService.review(p,2,mail.id().toString(),1,0);AuctionService.confirm(p,q.nonce());}for(var mail:new ArrayList<>(s.itemMailbox(other.getUUID())))if(!mail.claimed()){var q=AuctionService.review(other,2,mail.id().toString(),1,0);AuctionService.confirm(other,q.nonce());}
                h.assertTrue(s.taxRemoved()==6&&!s.order(order.id()).orElseThrow().active()&&!s.listing(listing.id()).orElseThrow().active(),"Real post-archive fill/cancel/settlement removes exact5plus1tax and closes escrow once");proof.putInt("phase",2);capture(s,p,other,proof);AtomicNbt.write(proofPath(h),proof);CommerceService.checkpoint(p);CommerceService.checkpoint(other);com.mojang.logging.LogUtils.getLogger().info("ARCHIVE_RESUMED: actual restarted earned profession, funded escrow, partial fill/refund, exact item/coin mail claims and6coin tax; real native receipts continue after archived prefix; timed deadline explicitly accelerated only in this fixture");
            }else{h.assertTrue(!s.order(proof.getUUID("order")).orElseThrow().active()&&!s.listing(proof.getUUID("listing")).orElseThrow().active()&&s.taxRemoved()==6,"Second actual restart retains closed escrow and tax sink without replay");h.assertTrue(s.itemMailbox(p.getUUID()).stream().allMatch(EconomyStore.ItemMail::claimed)&&s.itemMailbox(other.getUUID()).stream().allMatch(EconomyStore.ItemMail::claimed),"Claimed escrow deliveries cannot return after restart");com.mojang.logging.LogUtils.getLogger().info("ARCHIVE_VERIFIED: three actual dedicated JVMs preserve complete earned24Farmer/Master/equipment/community/contract state, original construction/NPC identities, both native receipts/purses, closed funded escrows and once-only deliveries/tax across immutable journal archival");}h.succeed();
        }));
    }
    private static void verifyEarned(GameTestHelper h,EconomyStore s,ServerPlayer p){var roster=s.professions(p.getUUID());h.assertTrue(roster.track(Profession.FARMER).completedQuestIds().size()==24&&roster.track(Profession.FARMER).xp()==4800&&roster.rank(Profession.FARMER,FarmerQuests.catalog())==ProfessionRank.MASTER&&s.equipmentPurchases(p.getUUID(),FarmerGear.FORTUNE_X_HOE.id())==1&&s.communityMasterProofs(p.getUUID())==3,"Every genuinely earned Farmer quest/rank/equipment/community record survives archived replay");}
    private static void capture(EconomyStore s,ServerPlayer p,ServerPlayer other,CompoundTag tag){tag.putLong("revision",s.revision());tag.putLong("ownerBalance",s.balance(p.getUUID()));tag.putLong("otherBalance",s.balance(other.getUUID()));tag.putLong("ownerReceipt",s.expectedReceipt(p.getUUID()));tag.putLong("otherReceipt",s.expectedReceipt(other.getUUID()));}
    private static ConstructionStore.Project bank(GameTestHelper h){return ConstructionService.store(h.getLevel().getServer()).projects().stream().filter(p->p.blueprint().equals(RoyalBankBlueprint.ID)).findFirst().orElseThrow();}
    private static int empty(ServerPlayer p){for(int i=0;i<36;i++)if(p.getInventory().getItem(i).isEmpty())return i;throw new IllegalStateException("No free native fixture slot");}
    private static void near(ServerPlayer p,net.minecraft.world.entity.Entity npc){Objects.requireNonNull(npc,"Resident chunk not loaded");var level=p.serverLevel();for(var pos:BlockPos.betweenClosed(npc.blockPosition().offset(-2,0,-2),npc.blockPosition().offset(2,0,2)))if(level.getBlockState(pos).isAir()&&level.getBlockState(pos.above()).isAir()&&level.getBlockState(pos.below()).isFaceSturdy(level,pos.below(),net.minecraft.core.Direction.UP)){p.moveTo(pos.getX()+.5,pos.getY(),pos.getZ()+.5);if(p.hasLineOfSight(npc)&&p.distanceToSqr(npc)<25)return;}throw new IllegalStateException("No clear actual Bank counter position");}
    private static void claimCoins(ServerPlayer p,UUID mail){var view=CommerceService.handle(p,new CommerceRequest(++requests,1,2,mail.toString(),1,CommerceRequest.NONE));if(!view.reviewing())throw new IllegalStateException(view.notice());CommerceService.handle(p,new CommerceRequest(++requests,2,2,"",1,view.review()));}
    private static int command(ServerPlayer p,String cmd)throws com.mojang.brigadier.exceptions.CommandSyntaxException{return p.server.getCommands().getDispatcher().execute(cmd,p.createCommandSourceStack());}
    private static String confirmation(ClaimRuntimeTests.ClaimPlayer p){for(int i=p.messages.size()-1;i>=0;i--){var command=p.messages.get(i).visit((style,text)->{var event=style.getClickEvent();return event!=null&&event.getAction()==ClickEvent.Action.RUN_COMMAND&&event.getValue().startsWith("/kingdom admin economy archive confirm ")?Optional.of(event.getValue().substring(1)):Optional.<String>empty();},Style.EMPTY);if(command.isPresent())return command.get();}throw new IllegalStateException("No actual clickable administrator archive review");}
    @FunctionalInterface private interface Action{void run()throws Exception;}
    private static void guard(GameTestHelper h,Action action){try{action.run();}catch(Exception e){com.mojang.logging.LogUtils.getLogger().error("Native economy archive verification failed",e);h.runAfterDelay(1,()->h.fail(e.toString()));}}
}
